mapper.select:
SELECT
    mqcmp.*,
    mbp.id AS 'process.id',
    mbp.name AS 'process.name'
FROM mes_quota_config_machine_part mqcmp
LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = mqcmp.process_id
WHERE mqcmp.bool_delete_enum = 0

    AND FIND_IN_SET(#{branchCompanyId}, mqcmp.branch_company_ids) > 0


    AND FIND_IN_SET(#{workshopId}, mqcmp.workshop_ids) > 0


    AND FIND_IN_SET(#{productClassId}, mqcmp.machine_part_class_ids) > 0


    AND mqcmp.process_id = #{processId}


    AND (
    
        FIND_IN_SET(#{bcId}, mqcmp.branch_company_ids) > 0
    
    )


    AND (
    
        FIND_IN_SET(#{wId}, mqcmp.workshop_ids) > 0
    
    )


    AND (
    
        mqcmp.product_classification_enum = #{pce}
    
    )


    AND (
    
        FIND_IN_SET(#{pcId}, mqcmp.machine_part_class_ids) > 0
    
    )


    AND (
    
        mqcmp.process_id = #{pId}
    
    )
